# Palette and widget styling adapted from the user-provided DIE Layout Studio v1.1.10.
STYLE = '\nQMainWindow, QDialog { background: #f4f6fa; }\nQWidget { font-size: 12px; color: #25334a; }\nQGroupBox { background: white; border: 1px solid #dae1eb; border-radius: 6px; margin-top: 0px; padding-top: 22px; }\nQGroupBox::title { subcontrol-origin: padding; subcontrol-position: top left; left: 9px; top: 5px; padding: 0px 4px; color: #000000; font-weight: bold; }\nQFrame#ParameterSection { background: white; border: 1px solid #dae1eb; border-radius: 6px; }\nQLabel#SectionTitle { color: #000000; font-weight: bold; background: white; border: none; padding: 0px; }\nQSplitter::handle { background: #d3deec; border: 1px solid #b8c7db; }\nQSplitter::handle:hover { background: #93b6df; }\nQSplitter::handle:vertical { margin: 1px 3px; }\nQSplitter::handle:horizontal { margin: 3px 1px; }\nQLabel:disabled, QCheckBox:disabled, QComboBox:disabled { color: #939eac; }\nQPushButton { padding: 6px 9px; border: 1px solid #cbd5e2; border-radius: 5px; background: white; min-height: 20px; }\nQPushButton:hover { background: #e9f0fc; border-color: #8daee4; }\nQPushButton:disabled { background: #f0f2f6; color: #a0a8b6; }\nQPushButton#Primary { background: #2863b9; color: white; border: 1px solid #2863b9; font-weight: bold; }\nQPushButton#Primary:hover { background: #21549d; }\nQDoubleSpinBox, QSpinBox, QComboBox, QLineEdit { background: white; border: 1px solid #cad3df; border-radius: 4px; padding: 4px; min-height: 18px; }\nQDoubleSpinBox:disabled, QSpinBox:disabled { color: #939eac; background: #f0f2f5; }\nQTabWidget::pane { border: 1px solid #d9e0e9; background: white; }\nQTabBar::tab { background: #eaf0f7; padding: 8px 10px; border: 1px solid #d6dfeb; }\nQTabBar::tab:selected { background: white; color: #245cae; }\nQTableView, QTableWidget { background: white; gridline-color: #e5eaf1; selection-background-color: #dceaff; selection-color: #192c4a; }\nQHeaderView::section { background: #eaf0f8; padding: 5px; border: 0; border-right: 1px solid #d8e0eb; font-weight: bold; }\nQLabel#Notice { background: #eaf1fb; border: 1px solid #d4e2f5; padding: 8px; border-radius: 5px; }\nQPlainTextEdit { background: #fbfcff; border: 1px solid #d6dfe9; font-family: Consolas, monospace; }\nQProgressBar { border: 1px solid #cbd5e2; border-radius: 4px; text-align: center; }\nQProgressBar::chunk { background: #487ec7; }\n'
